def choose_move(observation):
    w = observation["grid_width"]
    h = observation["grid_height"]
    sx, sy = observation["self_position"]
    ox, oy = observation["opponent_position"]
    res = observation.get("resources", []) or []
    obs_list = observation.get("obstacles", []) or []
    obstacles = set(tuple(p) for p in obs_list)

    def inb(x, y):
        return 0 <= x < w and 0 <= y < h

    moves = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]
    have_res = bool(res)
    if have_res:
        best = None
        for rx, ry in res:
            d = abs(rx - sx) + abs(ry - sy)
            if best is None or d < best[0] or (d == best[0] and (rx, ry) < best[1]):
                best = (d, (rx, ry))
        tx, ty = best[1]
    else:
        tx, ty = - (ox - sx), - (oy - sy)  # direction to move away

    candidates = []
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if inb(nx, ny) and (nx, ny) not in obstacles:
            if have_res:
                score = abs(tx - nx) + abs(ty - ny)
            else:
                score = -(abs(nx - ox) + abs(ny - oy))
            candidates.append((score, dx, dy))
    if not candidates:
        return [0, 0]
    candidates.sort(key=lambda t: (t[0], t[1], t[2]))
    return [candidates[0][1], candidates[0][2]]

def choose_move(observation):
    w = observation.get("grid_width", 8)
    h = observation.get("grid_height", 8)
    self_pos = observation.get("self_position", [0, 0])
    opp_pos = observation.get("opponent_position", [w - 1, h - 1])
    sx, sy = int(self_pos[0]), int(self_pos[1])
    ox, oy = int(opp_pos[0]), int(opp_pos[1])

    obstacles = observation.get("obstacles", []) or []
    obs = set()
    for p in obstacles:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            obs.add((int(p[0]), int(p[1])))

    resources = observation.get("resources", []) or []
    if not resources:
        return [0, 0]

    moves = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    def legal(nx, ny):
        return 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obs

    def man(a, b, c, d):
        return abs(a - c) + abs(b - d)

    opp_best = 10**9
    for r in resources:
        rx, ry = int(r[0]), int(r[1])
        d = man(ox, oy, rx, ry)
        if d < opp_best:
            opp_best = d

    best_move = (0, 0)
    best_score = None

    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not legal(nx, ny):
            continue
        self_best = 10**9
        for r in resources:
            rx, ry = int(r[0]), int(r[1])
            d = man(nx, ny, rx, ry)
            if d < self_best:
                self_best = d
        advantage = opp_best - self_best
        score = (advantage, -self_best, dx, dy)
        if best_score is None or score > best_score:
            best_score = score
            best_move = (dx, dy)

    return [int(best_move[0]), int(best_move[1])]

def choose_move(observation):
    w = observation["grid_width"]
    h = observation["grid_height"]
    sx, sy = observation["self_position"]
    ox, oy = observation["opponent_position"]
    obstacles = set(tuple(p) for p in (observation.get("obstacles", []) or []))
    resources = observation.get("resources", []) or []
    moves = [(-1,-1),(-1,0),(-1,1),(0,-1),(0,0),(0,1),(1,-1),(1,0),(1,1)]

    def inb(x, y):
        return 0 <= x < w and 0 <= y < h

    def man(ax, ay, bx, by):
        return abs(ax - bx) + abs(ay - by)

    def cell_ok(x, y):
        return (x, y) not in obstacles

    best = None
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not inb(nx, ny) or not cell_ok(nx, ny):
            continue

        if resources:
            # nearest resource; tie-break by keeping distance from opponent
            md = 10**9
            for rx, ry in resources:
                d = man(nx, ny, rx, ry)
                if d < md:
                    md = d
            od = man(nx, ny, ox, oy)
            # maximize: prefer smaller md (encode as negative), prefer larger od
            key = (-md, od, dx, dy)
        else:
            # no resources: maximize distance from opponent
            od = man(nx, ny, ox, oy)
            key = (od, -(abs(nx - (w - 1) // 2) + abs(ny - (h - 1) // 2)), dx, dy)

        if best is None or key > best[0]:
            best = (key, [dx, dy])

    if best is None:
        return [0, 0]
    return best[1]

